#include <iostream>

// Recursive function to compute the nth Fibonacci number
long long fibonacci(int n) {
    // Base cases
    if (n <= 0) return 0;
    if (n == 1) return 1;

    // Recursive calls
    return fibonacci(n - 1) + fibonacci(n - 2);
}

int main() {
    int n;

    std::cout << "Enter a non-negative integer n: ";
    if (!(std::cin >> n) || n < 0) {
        std::cerr << "Invalid input. Please enter a non-negative integer.\n";
        return 1;
    }

    long long result = fibonacci(n);

    std::cout << "The " << n << "th Fibonacci number is: " << result << "\n";

    return 0;
}
```

**Notes:**
- This implementation uses pure recursion, which is simple but has exponential time complexity O(2ⁿ). For large `n`, consider using memoization or an iterative approach.
- The function returns `long long` to avoid overflow for moderate values of `n`. For very large `n`, you may need a big integer library.

